\section{The \texorpdfstring{$\mG$}{mG} Language for Graph Neural Networks}\label{sec:mg}

In this section, we introduce the syntax of $\mG$ as a programming language for the definition of graph neural networks. After specifying its syntax (Definition~\ref{def:syntax}), we show its denotational semantics (Definition~\ref{def:denotational_semantics}), and structural operational semantics (Definition \ref{def:sos}). 

\begin{definition}[Syntax of $\mG$]\label{def:syntax}
Given a set $\mathcal{S}$ of function symbols, we define an algebra of graph neural networks with the following abstract syntax:
\begin{normalfont}
\begin{align*} 
\mathcal{N} ::=& \; \id \mid \psi \mid \lhd_{\sigma}^{\varphi} \mid \rhd_{\sigma}^{\varphi} \mid \mathcal{N}_1 ; \mathcal{N}_2 \mid \mathcal{N}_1 || \mathcal{N}_2 \mid 
\mathcal{N}_1 \choiceop \mathcal{N}_2 \mid  \starop{\mathcal{N}} 
\end{align*}
\end{normalfont}
\noindent with $\varphi, \sigma, \psi \in \mathcal{S}$. The operator precedence rules given by $\starop{} > \, ; \, > || > \choiceop$ and round parentheses are introduced to the syntax to make the meaning of expressions unambiguous.
\end{definition}

Given a graph $\graph$ and an edge-labeling $\lblfune$, the meaning of a $\mG$ expression is a graph neural network, a partial function between node-labeling functions.
%
The term $\id$ represents the application of the \textit{identity} GNN that leaves the node labels unaltered.
%
Another of the basic $\mG$ terms is the \emph{function application} $\psi$. This represents the GNN that applies the function associated with $\psi$.
%
Moreover, the \emph{pre-image} term $\lhd_{\sigma}^{\varphi}$ and the \emph{post-image} term $\rhd_{\sigma}^{\varphi}$ define a GNN that computes the labeling of a node in terms of the labels of its predecessors and successors, respectively, using functions associated with symbols $\sigma$ and $\varphi$.
%
Two GNNs can be composed by \emph{sequential composition} $\mathcal{N}_1 ; \mathcal{N}_2$ and \emph{parallel composition} $\mathcal{N}_1 || \mathcal{N}_2$. 
%
% Local \emph{variables} $X$ and \emph{functions} $f(\Tilde{X})$ can be defined using \texttt{let} and \texttt{def}.
%
The \textit{choice} operator $\mathcal{N}_1 \choiceop \mathcal{N}_2$ allows to run different GNNs according to the values of a node-labeling function.
%
Finally, the \emph{star} operator $\starop{\mathcal{N}}$ is used to program recursive behavior. 
%
%We say that a variable $X$ is \emph{bound} in $\mathcal{N}$ if it only occurs under the scope of a fixpoint operator or a function definition. We say that $X$ is \emph{free} in $\mathcal{N}$ if it is not \emph{bound}.

\subsection{Denotational semantics}
Having defined the syntax, we are now ready to introduce the denotational semantics of $\mG$.

\begin{definition}{(Denotational semantics)} \label{def:denotational_semantics}
Given a graph $\graph$ and an edge-labeling function $\lblfune$, we define the semantic interpretation function $\ds{\cdot}: \mathcal{N} \rightarrow \gnntypews$ on $\mu\mathcal{G}$ formulas $\mathcal{N}$ by induction in the following way:
\begin{normalfont}
\begin{align*}
&\ds{\id} = id \\
&\ds{\psi}(\lblfunv)  = \lambda v . f_{\psi}(\lblfunv(\vSet), \lblfunv(v)) \\
&\ds{\lhd_{\sigma}^{\varphi}}(\lblfunv) =  \lambda v . f_\sigma([f_\varphi(\lblfunv(u), \lblfune((u, v)), \lblfunv(v)) \mid (u, v) \in \inset{\graph}{v}], \lblfunv(v)) \\
&\ds{\rhd_{\sigma}^{\varphi}}(\lblfunv) =  \lambda v . f_\sigma([f_\varphi(\lblfunv(u), \lblfune((v, u)), \lblfunv(v)) \mid (v, u) \in \outset{\graph}{v}], 
\lblfunv(v)) \\
&\ds{\mathcal{N}_1 ; \mathcal{N}_2}  = \ds{\mathcal{N}_2} \circ \ds{\mathcal{N}_1} \\
&\ds{\mathcal{N}_1 || \mathcal{N}_2} = \ds{\mathcal{N}_1} \gnncomp \ds{\mathcal{N}_2}\\
&\ds{\mathcal{N}_1 \choiceop \mathcal{N}_2} = cond(\pi_L, \ds{\mathcal{N}_1} \circ \pi_R, \ds{\mathcal{N}_2} \circ \pi_R)\\
&\ds{\starop{\mathcal{N}}} = FIX(\lambda \gnnws .  cond(\lambda e . \lambda v . \ds{\mathcal{N}}(e)(v) \simop e(v), id, \gnnws \circ \ds{\mathcal{N}}))
\end{align*}
\end{normalfont}
for any $\psi, \varphi, \sigma \in \mathcal{S}$ and any $f_\psi:T_1^\star \times T_1 \rightarrow T_2, f_\varphi: T_1 \times T_e \times T_1 \rightarrow T_2, f_\sigma: T_2^\star \times T_1 \rightarrow T_3$. The functions $cond$ and $FIX$ are defined as:

\[
cond(t, f_{1}, f_{2})(\lblfunv) = \begin{cases} 
f_{1}(\lblfunv) & \text{if } t(\lblfunv) = \lambda v . \mathtt{True} \\
f_{2}(\lblfunv) & \text{otherwise}
\end{cases}
\]
%where $\lblfunv_{\mathtt{True}}$ denotes the constant node-labeling function that maps every node to the Boolean $\mathtt{True}$ value.
% \[
%   g(\gnnws)(\lblfunv) = \begin{cases}
% \gnnws(\lblfunv) & \text{if } \gnnws(\lblfunv) = \ds[{[X \leftarrow \gnnws]}]{\mathcal{N}_2}(\lblfunv)\\
% g(\lambda e . \ds[{[X \leftarrow \gnnws]}]{\mathcal{N}_2}(\lblfunv))(\lblfunv) & \text{otherwise}
% \end{cases}  
% \]

\[FIX(f) = \bigsqcup \{f^n(\bot_{\gnntypews}) \mid n \geq 0 \}\]
where $f^0 = id$ and $f^{n+1} = f \circ f^n$.
%
For any label type $T$ and any rational value $\epsilon \in \mathbb{Q}$, we define a binary predicate $\simop$ such that $\forall x, y \in T$
\[x \simop y \iff (x = y) \lor (\exists k \in \mathbb{N}. T \subseteq \mathbb{Q}^k \land \forall i \in \{1,\ldots, k\} . |x_i - y_i| \leq \epsilon) \]
%
This predicate specifies that for two labels to be considered the ``same'' they must either be exactly equal, or they must consist of numerical values and each of those values must not differ by more than $\epsilon$ at most.

%
% \[
