The rules $\texttt{PAR}_1$ and $\texttt{PAR}_2$ in Table~\ref{tab:structural_semantics} may give rise to multiple derivation sequences for a given $\mG$ expression. The next theorem shows that no matter the order of application of the structural semantics rules, the obtained graph neural network has the same input-output behavior, and we say that in this sense, the operational semantics are \textit{deterministic}.

\begin{theorem}[Strong Confluence]\label{th:confluence}
    If $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}_1}{\lblfunv_1}$ and $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}_2}{\lblfunv_2}$, then there exists a term $\mathcal{N}'$ and a labeling function $\lblfunv'$ such that $\sos[\star]{\mathcal{N}_1}{\lblfunv_1}{\mathcal{N}'}{\lblfunv'}$ and either $\sos{\mathcal{N}_2}{\lblfunv_2}{\mathcal{N}'}{\lblfunv'}$ or $\mathcal{N}' = \mathcal{N}_2$ and $\lblfunv' = \lblfunv_2$.
\end{theorem}

% \begin{theorem}[Confluence]\label{th:confluence}
%     If $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}_1}{\lblfunv_1}$ and $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}_2}{\lblfunv_2}$, then either $\mathcal{N}_1 = \mathcal{N}_2$ and $\lblfunv_1 = \lblfunv_2$ or there exists a term $\mathcal{N}'$ and a labeling function $\lblfunv'$ such that $\sos{\mathcal{N}_1}{\lblfunv_1}{\mathcal{N}'}{\lblfunv'}$ and $\sos{\mathcal{N}_2}{\lblfunv_2}{\mathcal{N}'}{\lblfunv'}$.
% \end{theorem}
\begin{proof}
    By induction on the structure of the derivation sequences. The only interesting case is that for rules $\texttt{PAR}_1$ and $\texttt{PAR}_2$, which can both be applied on expressions of the form $\mathcal{N}_1 \parcomp \mathcal{N}_2$. Suppose that $\sos{\mathcal{N}_1 \parcomp \mathcal{N}_2}{\lblfunv}{\mathcal{N}_1' \parcomp \mathcal{N}_2}{\lblfunv_1 | \pi_R(\lblfunv)}$ by rule $\texttt{PAR}_1$ and that $\sos{\mathcal{N}_1 \parcomp \mathcal{N}_2}{\lblfunv}{\mathcal{N}_1 \parcomp \mathcal{N}_2'}{\pi_L(\lblfunv) | \lblfunv_2}$ by rule $\texttt{PAR}_2$.   
    Then the required term is $\mathcal{N}' = \mathcal{N}_1' \parcomp \mathcal{N}_2'$ and the labeling function is $\lblfunv' = \lblfunv_1 | \lblfunv_2$, because $\sos{\mathcal{N}_1' \parcomp \mathcal{N}_2}{\lblfunv_1 | \pi_R(\lblfunv)}{\mathcal{N}_1' \parcomp \mathcal{N}_2'}{\lblfunv_1 | \lblfunv_2}$ by rule $\texttt{PAR}_2$ and $\sos{\mathcal{N}_1 \parcomp \mathcal{N}_2'}{\pi_L(\lblfunv) | \lblfunv_2}{\mathcal{N}_1' \parcomp \mathcal{N}_2'}{\lblfunv_1 | \lblfunv_2}$ by rule $\texttt{PAR}_1$.
\end{proof}

Finally, we can define the semantic interpretation function on the structural operational semantics. 

\begin{definition}[Structural operational semantics]\label{def:sos}
Given a graph $\graph$ and an edge-labeling function $\lblfune$, we define the semantic interpretation function $\sosf{\cdot}: \mathcal{N} \rightarrow \gnntypews$ such that \[
    \sosf{\mathcal{N}}(\lblfunv) = \begin{cases}
        \lblfunv' & \text{if } \sosv[\star]{\mathcal{N}}{\lblfunv}{\lblfunv'} \\
        \texttt{undef} & \text{otherwise}
    \end{cases}
\]
\end{definition}


