\item[The case $\mathcal{N}_1 || \mathcal{N}_2$:] By induction hypothesis we have $\ds{\mathcal{N}_1} \gnnorder \sosf{\mathcal{N}_1}$ and $\ds{\mathcal{N}_2} \gnnorder \sosf{\mathcal{N}_2}$. By the monotonicity of $\gnncomp$ in both its arguments (Lemma~\ref{lemma:cont-par}) and the induction hypothesis, we get that
\begin{align*}
    \ds{\mathcal{N}_1 || \mathcal{N}_2}  &= \ds{\mathcal{N}_1} \gnncomp \ds{\mathcal{N}_2} \\
                                         &\gnnorder \sosf{\mathcal{N}_1} \gnncomp \sosf{\mathcal{N}_2}
\end{align*}
%
%
% We have that $\ds{\mathcal{N}_1 || \mathcal{N}_2}(\lblfunv) = \ds{\mathcal{N}_1}(\lblfunv) | \ds{\mathcal{N}_2}(\lblfunv)$ and by induction hypothesis we have $\sosv[\star]{\mathcal{N}_1}{\lblfunv}{\ds{\mathcal{N}_1}(\lblfunv)}$ and $\sosv[\star]{\mathcal{N}_2}{\lblfunv}{\ds{\mathcal{N}_2}(\lblfunv)}$. 
%
To continue the proof, we show that if $\sosv[k_1]{\mathcal{N}_1}{\lblfunv_1}{\lblfunv_1'}$ and $\sosv[k_2]{\mathcal{N}_2}{\lblfunv_2}{\lblfunv_2'}$, then $\sosv[k_1 + k_2]{\mathcal{N}_1 \parcomp \mathcal{N}_2}{\lblfunv_1 | \lblfunv_2}{\lblfunv_1' | \lblfunv_2'}$. For $k_1 = k_2 = 1$, we have that $\mathcal{N}_1 = \mathcal{N}_2 = \id$, $\lblfunv_1 = \lblfunv_1'$ and $\lblfunv_2 = \lblfunv_2'$. Hence, we get $\sosv{\id \parcomp \id}{\lblfunv_1 | \lblfunv_2}{\sosv{\id}{\lblfunv_1 | \lblfunv_2}{\lblfunv_1 | \lblfunv_2}}$ by applying rule \texttt{MERGE} followed by rule \texttt{ID} and performing $1 + 1 = 2$ steps. For the inductive step, let's assume the implication holds for $k_1, k_2$ and prove it for $k_1 + 1, k_2 + 1$. We have $\sosv{\mathcal{N}_1}{\lblfunv_1}{\sosv[k_1]{\mathcal{N}_1'}{\lblfunv_1''}{\lblfunv_1'}}$ and $\sosv{\mathcal{N}_2}{\lblfunv_2}{\sosv[k_2]{\mathcal{N}_2'}{\lblfunv_2''}{\lblfunv_2'}}$ for some $\mathcal{N}_1', \mathcal{N}_2', \lblfunv_1'', \lblfunv_2''$. Then we can perform two steps $\sosv{\mathcal{N}_1 \parcomp \mathcal{N}_2}{\lblfunv_1 | \lblfunv_2}{\sos{\mathcal{N}_1' \parcomp \mathcal{N}_2}{\lblfunv_1'' | \lblfunv_2}{\mathcal{N}_1' \parcomp \mathcal{N}_2'}{\lblfunv_1'' | \lblfunv_2''}}$ by applying rules [$\texttt{PAR}_1$] and [$\texttt{PAR}_2$]. Then by applying the induction hypothesis we get our result $\sosv[k_1 + k_2]{\mathcal{N}_1' \parcomp \mathcal{N}_2'}{\lblfunv_1'' | \lblfunv_2''}{\lblfunv_1' | \lblfunv_2'}$ in $2 + k_1 + k_2 = (k_1 + 1) + (k_2 + 1)$ steps.
%
Using this result, we can conclude that
% \sosf{\mathcal{N}_1 || \mathcal{N}_2}
\begin{align*}
    \sosf{\mathcal{N}_2} \gnncomp \sosf{\mathcal{N}_1} &\gnnorder \sosf{\mathcal{N}_1 \parcomp \mathcal{N}_2} \circ (id \gnncomp id)\\
                                                       &= \sosf{\mathcal{N}_1 || \mathcal{N}_2}
\end{align*}
%
as required.
%
% Now we can continue our proof. Using rule \texttt{SPLIT} we get $\sosv{\mathcal{N}_1 || \mathcal{N}_2}{\lblfunv}{\soscomp{\mathcal{N}_1}{\lblfunv} \otimes \soscomp{\mathcal{N}_2}{\lblfunv}}$. Now we can apply the lemma to the induction hypothesis to get $\vsosv[\star]{\soscomp{\mathcal{N}_1}{\lblfunv} \otimes \soscomp{\mathcal{N}_2}{\lblfunv}}{\ds{\mathcal{N}_1}(\lblfunv) | \ds{\mathcal{N}_2}(\lblfunv)}$.
%
%
\item[The case $\mathcal{N}_1 \parcomp \mathcal{N}_2$:] By induction hypothesis we have $\ds{\mathcal{N}_1} \gnnorder \sosf{\mathcal{N}_1}$ and $\ds{\mathcal{N}_2} \gnnorder \sosf{\mathcal{N}_2}$. By the monotonicity of $\circ$ (Lemma~\ref{lemma:cont-circ}) and that of $\gnncomp$ in both its arguments (Lemma~\ref{lemma:cont-par}), and the induction hypothesis, we get that
\begin{align*}
    \ds{\mathcal{N}_1 \parcomp \mathcal{N}_2}  &= (\ds{\mathcal{N}_1} \circ \pi_L) \gnncomp (\ds{\mathcal{N}_1} \circ \pi_R) \\
                                         &\gnnorder (\sosf{\mathcal{N}_1} \circ \pi_L) \gnncomp (\sosf{\mathcal{N}_2} \circ \pi_R)\\
                                         &= \sosf{\mathcal{N}_1 \parcomp \mathcal{N}_2}
\end{align*}


\item[The case $\mathcal{N}_1 \choiceop \mathcal{N}_2$:] We have that $\ds{\mathcal{N}_1 \choiceop \mathcal{N}_2} = cond(\pi_L, \ds{\mathcal{N}_1} \circ \pi_R, \ds{\mathcal{N}_2} \circ \pi_R)$. By induction hypothesis we have that $\ds{\mathcal{N}_1} \gnnorder \sosf{\mathcal{N}_1}$ and $\ds{\mathcal{N}_2} \gnnorder \sosf{\mathcal{N}_2}$.
%
By the monotonicity of $\circ$ (Lemma~\ref{lemma:cont-circ}) and that of $cond$ in its second and third arguments (Lemma~\ref{lemma:cont-cond2}), and the induction hypothesis we have that
%
\begin{align*}
    \ds{\mathcal{N}_1 \choiceop \mathcal{N}_2}  &= cond(\pi_L, \ds{\mathcal{N}_1} \circ \pi_R, \ds{\mathcal{N}_2} \circ \pi_R) \\
    &\gnnorder cond(\pi_L, \sosf{\mathcal{N}_1} \circ \pi_R, \sosf{\mathcal{N}_2} \circ \pi_R)
\end{align*}
%
Now from the rules $\texttt{CHOICE}_1$ and $\texttt{CHOICE}_2$ it follows that
%
\begin{align*}
    \sosf{\mathcal{N}_1 \choiceop \mathcal{N}_2}(\lblfunv) = \sosf{\mathcal{N}_1}(\pi_R(\lblfunv)) & \text{ if } \pi_L(\lblfunv) = \lambda v . \mathtt{True} \\
    \sosf{\mathcal{N}_1 \choiceop \mathcal{N}_2}(\lblfunv) = \sosf{\mathcal{N}_2}(\pi_R(\lblfunv)) & \text{ if } \pi_L(\lblfunv) \neq \lambda v . \mathtt{True}
\end{align*}
%
therefore
%
\[cond(\pi_L, \sosf{\mathcal{N}_1} \circ \pi_R, \sosf{\mathcal{N}_2} \circ \pi_R) = \sosf{\mathcal{N}_1 \choiceop \mathcal{N}_2}\]

% We consider two possible cases, whether $\pi_L(\lblfunv) = \lambda v . \mathtt{True}$ or not. In the former case, we have $cond(\lambda v . \mathtt{True}, \ds{\mathcal{N}_1}(\pi_R(\lblfunv)), \ds{\mathcal{N}_2}(\pi_R(\lblfunv))) = \ds{\mathcal{N}_1}(\pi_R(\lblfunv))$ and by applying rule $\texttt{CHOICE}_1$ we get $\sos{\mathcal{N}_1 \choiceop \mathcal{N}_2}{\lblfunv}{\mathcal{N}_1}{\pi_R(\lblfunv)}$. Then by induction hypothesis we get $\sosv[\star]{\mathcal{N}_1}{\pi_R(\lblfunv)}{\ds{\mathcal{N}_1}(\pi_R(\lblfunv))}$. In the latter case the proof is analogous, but instead we apply rule $\texttt{CHOICE}_2$ to get $\sos{\mathcal{N}_1 \choiceop \mathcal{N}_2}{\lblfunv}{\mathcal{N}_2}{\pi_R(\lblfunv)}$. Then by induction hypothesis we get $\sosv[\star]{\mathcal{N}_2}{\pi_R(\lblfunv)}{\ds{\mathcal{N}_2}(\pi_R(\lblfunv))}$.

\item[The case $\starop{\mathcal{N}}$:] We have that $\ds{\starop{\mathcal{N}}} = FIX(F)$, where
%
\[F = \lambda \gnnws .  cond(\lambda e . \lambda v . \ds{\mathcal{N}}(e)(v) \simop e(v), id, \gnnws \circ \ds{\mathcal{N}})\] 
%
We start by proving that if $f: D \rightarrow D$ is a continuous function on a ccpo $(D, \sqsubseteq)$ and if $d \in D$ is such that $f(d) \sqsubseteq d$, then $FIX(f) \sqsubseteq d$. To prove this, we recall that by the monotonicity of $f$ it must be the case that $f(f(d)) \sqsubseteq f(d)$, and more generally, that $f^{n+1}(d) \sqsubseteq f^n(d), \forall n \geq 0$. Therefore $d$ is an upper bound of the chain $\{f^n(d) \mid n \geq 0\}$. Then, since $\bot \sqsubseteq d$, we have that $f^n(\bot) \sqsubseteq f^n(d), \forall n \geq 0$ and $d$ is also an upper bound for the chain $\{f^n(\bot) \mid n \geq 0\}$. Then $FIX(f) = \bigsqcup \{f^n(\bot) \mid n \geq 0\} \sqsubseteq d$ since the least fixed point of $f$ is the least upper bound of that chain.

This result proves that $FIX(F) \sqsubseteq \sosf{\starop{\mathcal{N}}}$, on the condition that we show that $F(\sosf{\starop{\mathcal{N}}}) \sqsubseteq \sosf{\starop{\mathcal{N}}}$.  We can prove this by first showing that
%
\begin{align*}
    \sosf{\starop{\mathcal{N}}} &= \sosf{((\mathcal{N} || \id) ; \psi_{\simop} || \id) ; (\id \choiceop \mathcal{N} ; \starop{\mathcal{N}})}\\
    &\sqsupseteq \sosf{(\id \choiceop \mathcal{N} ; \starop{\mathcal{N}})} \circ \sosf{((\mathcal{N} || \id) ; \psi_{\simop} || \id)}\\
    &= cond(\pi_L, \sosf{\id} \circ \pi_R,  \sosf{\mathcal{N} ; \starop{\mathcal{N}}} \circ \pi_R) \circ \sosf{((\mathcal{N} || \id) ; \psi_{\simop} || \id)}\\
    &= cond(\sosf{(\mathcal{N} || \id) ; \psi_{\simop}}, \sosf{\id}, \sosf{\mathcal{N} ; \starop{\mathcal{N}}})\\
    &\sqsupseteq  cond(\sosf{(\mathcal{N} || \id) ; \psi_{\simop}}, \sosf{\id}, \sosf{\starop{\mathcal{N}}} \circ \sosf{\mathcal{N}})
\end{align*}
%
The induction hypothesis gives us that $\ds{\mathcal{N}} \sqsubseteq \sosf{\mathcal{N}}$, and by the monotonicity of $\circ$ (Lemma~\ref{lemma:cont-circ}) and $cond$ (Lemmas~\ref{lemma:cont-cond1} and~\ref{lemma:cont-cond2}) we get
%
\begin{align*}
    \sosf{\starop{\mathcal{N}}} &\sqsupseteq  cond(\sosf{(\mathcal{N} || \id) ; \psi_{\simop}}, \sosf{\id}, \sosf{\starop{\mathcal{N}}} \circ \sosf{\mathcal{N}})\\
    &\sqsupseteq cond(\ds{(\mathcal{N} || \id) ; \psi_{\simop}}, id, \sosf{\starop{\mathcal{N}}} \circ \ds{\mathcal{N}})\\
    &= F(\sosf{\starop{\mathcal{N}}})
\end{align*}
%
%This completes our proof of Lemma~\ref{lemma:ds-to-sos}.
\end{description}
\end{proof}


\section{Type soundness}\label{sec:types}
%
\begin{table}[ht]
\centering
\begin{tabular}{lc}
[\texttt{T-ID}] & $\id: \gnntype{T}{T}$ \\[5mm]

[\texttt{T-PSI}] & \inference{\Gamma |- f_{\psi}: T^{\star}_{1} \times T_1 \rightarrow T_2}{\psi: \gnntype{T_1}{T_2}} \\[5mm]

[\texttt{T-PRE}]  & \inference{\Gamma |- f_\varphi: T_1 \times T_e \times T_1 \rightarrow T_2 & \Gamma |- f_\sigma: T_{2}^{\star} \times T_1 \rightarrow T_3}{\lhd_{\sigma}^{\varphi}: \gnntype{T_1}{T_3}} \\[5mm]

[\texttt{T-POST}]  & \inference{\Gamma |- f_\varphi: T_1 \times T_e \times T_1 \rightarrow T_2 & \Gamma |- f_\sigma: T_{2}^{\star} \times T_1 \rightarrow T_3}{\rhd_{\sigma}^{\varphi}: \gnntype{T_1}{T_3}} \\[5mm]

[\texttt{T-SEQ}] & \inference{\mathcal{N}_1: \gnntype{T_1}{T_2} & \mathcal{N}_2: \gnntype{T_2}{T_3}}{\mathcal{N}_1;\mathcal{N}_2: \gnntype{T_1}{T_3}} \\[5mm]

[\texttt{T-PAR}] & \inference{\mathcal{N}_1: \gnntype{T}{T_1} & \mathcal{N}_2: \gnntype{T}{T_2}}{\mathcal{N}_1 || \mathcal{N}_2: \gnntype{T}{T_1 \times T_2}} \\[5mm]

[\texttt{T-PROD}] & \inference{\mathcal{N}_1: \gnntype{T_1}{T_1'} & \mathcal{N}_2: \gnntype{T_2}{T_2'}}{\mathcal{N}_1 \parcomp \mathcal{N}_2: \gnntype{T_1 \times T_2}{T_1' \times T_2'}} \\[5mm]

[\texttt{T-CHOICE}] & \inference{\mathcal{N}_1: \gnntype{T_1}{T_2} & \mathcal{N}_2: \gnntype{T_1}{T_2}}{\mathcal{N}_1 \choiceop \mathcal{N}_2: \gnntype{\mathbb{B} \times T_1}{T_2}}  \\[5mm]

[\texttt{T-STAR}] & \inference{\mathcal{N} : \gnntype{T}{T}}{\starop{\mathcal{N}}: \gnntype{T}{T}}  \\[5mm]

\end{tabular}%}
\caption{Typing rules of $\mG$.}
\label{Tab:gnn_types}
\end{table}
%
%
We say that a $\mG$ term is \emph{well-typed} whenever it can be typed with the rules of Table~\ref{Tab:gnn_types}. These rules guarantee that any \emph{well-typed} $\mG$ term defines a graph neural network. Next, we will be using these typing rules to prove the type soundness of the operational semantics of $\mG$. Proving that $\mG$ is type safe ensures that the GNNs we program with it handle the data types correctly and produce results of the expected type. Concretely, this means that well-typed GNNs can always progress to the next step of computation and that after each step the type of the output is preserved.
%
%
\begin{theorem}[Type soundness]
If $\mathcal{N}: \gnntype{T_1}{T_2}$, $\lblfunv : \lblfunvtype{T_1}$ and $\sosv[\star]{\mathcal{N}}{\lblfunv}{\lblfunv'}$, then $\lblfunv' : \lblfunvtype{T_2}$.
\end{theorem}
\begin{proof}
Follows from Lemma~\ref{lemma:progress} (Progress) and Lemma~\ref{lemma:preservation} (Preservation).
\end{proof}
%
%
\begin{lemma}[Progress]\label{lemma:progress}
Suppose that $\mathcal{N}$ is a well-typed term $\mathcal{N}: \gnntype{T_1}{T_2}$ and that $\lblfunv: \lblfunvtype{T_1}$, then either $\mathcal{N} = \id$ or there exists $\mathcal{N}', \lblfunv'$ such that $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}'}{\lblfunv'}$.
\end{lemma}
%
\begin{proof}
    By induction on typing derivations. It suffices to show that either $\mathcal{N} = \id$ or there exists an operational rule that can be applied.
    \begin{description}
        \item[Case \texttt{T-ID}:] Immediate, as $\mathcal{N} = \id$.
        \item[Case \texttt{T-PSI}:] We have $\mathcal{N} = \psi$ and therefore can use rule \texttt{APPLY}.
        \item[Case \texttt{T-PRE}:] We have $\mathcal{N} = \lhd_\sigma^\varphi$ and therefore can use rule \texttt{PREIMG}.
        \item[Case \texttt{T-POST}:] We have $\mathcal{N} = \rhd_\sigma^\varphi$ and therefore can use rule \texttt{POSTIMG}.
        \item[Case \texttt{T-SEQ}:] We have $\mathcal{N} = \mathcal{N}_1 ; \mathcal{N}_2$ where $\mathcal{N}_1 : \gnntype{T_1}{T}$ and $\mathcal{N}_2 : \gnntype{T}{T_2}$. By induction hypothesis $\mathcal{N}_1$ is either $\id$ or it is possible to apply a transition rule. In the former case, we can apply rule $\texttt{SEQ}_2$, while in the latter case we can apply rule $\texttt{SEQ}_1$.
        \item[Case \texttt{T-PAR}:]  We have $\mathcal{N} = \mathcal{N}_1 || \mathcal{N}_2$ where $\mathcal{N}_1 : \gnntype{T}{T_1}$ and $\mathcal{N}_2 : \gnntype{T}{T_2}$. In this case, we can use rule \texttt{SPLIT}.
        \item[Case \texttt{T-PROD}:] We have $\mathcal{N} = \mathcal{N}_1 \parcomp \mathcal{N}_2$ where $\mathcal{N}_1 : \gnntype{T_1}{T_1'}$ and $\mathcal{N}_2 : \gnntype{T_2}{T_2'}$. By induction hypothesis $\mathcal{N}_1$ and $\mathcal{N}_2$ are either $\id$ or is it possible to apply a transition rule. Then,
        \begin{itemize}
            \item if $\mathcal{N}_1 = \id$ and $\mathcal{N}_2 = \id$, we can apply rule \texttt{MERGE}.
            \item if $\mathcal{N}_1 \neq \id$ and $\mathcal{N}_2 = \id$, we can apply rule $\texttt{PAR}_1$.
            \item if $\mathcal{N}_1 = \id$ and   $\mathcal{N}_2 \neq \id$, we can apply rule $\texttt{PAR}_2$.
            \item if $\mathcal{N}_1 \neq \id$ and $\mathcal{N}_2 \neq \id$, we can apply either rule $\texttt{PAR}_1$ or rule $\texttt{PAR}_2$.
        \end{itemize}
        \item[Case \texttt{T-CHOICE}:] We have $\mathcal{N} = \mathcal{N}_1 \choiceop \mathcal{N}_2 : \gnntype{\mathbb{B} \times T_1}{T_2}$ where $\mathcal{N}_1 : \gnntype{T_1}{T_2}$ and $\mathcal{N}_2 : \gnntype{T_1}{T_2}$. Furthermore, we have that $\lblfunv: \lblfunvtype{\mathbb{B} \times T_1}$. If $\pi_L(\lblfunv)$ is the constant node-labeling function that maps every node to \texttt{True}, we apply rule $\texttt{CHOICE}_1$. In any other case we apply rule $\texttt{CHOICE}_2$.
        \item[Case \texttt{T-STAR}:]  We have $\mathcal{N} = \starop{\mathcal{N}_1}$ where $\mathcal{N}_1 : \gnntype{T}{T}$. We can apply rule \texttt{STAR}.
    \end{description}
\end{proof}
%
%
\begin{lemma}[Preservation]\label{lemma:preservation}
% If $\mathcal{N}: \gnntype{T_1}{T_2}$, $\lblfunv: \lblfunvtype{T_1}$ and $\sos{\mathcal{N}}{\lblfunv}{\mathcal{N}'}{\lblfunv'}$, then $\mathcal{N}': \gnntype{T'}{T_2}$ and $\lblfunv': \lblfunvtype{T'}$.
If $\mathcal{N}: \gnntype{T_1}{T_2}$, $\lblfunv: \lblfunvtype{T_1}$, and $\sosv{\mathcal{N}}{\lblfunv}{\gamma}$
\begin{itemize}
    \item if $\gamma = \soscomp{\mathcal{N}'}{\lblfunv'}$, then $\mathcal{N}': \gnntype{T'}{T_2}$ and $\lblfunv': \lblfunvtype{T'}$, for some label type $T'$.
    \item if $\gamma = \lblfunv'$, then $\lblfunv': \lblfunvtype{T_2}$.
\end{itemize}

\end{lemma}
%[\texttt{APPLY}] &
% $\sos{\psi}{\lblfunv}{\id}{\lambda v . f_{\psi}(\lblfunv(\vSet), \lblfunv(v))}$ \\[5mm]

% [\texttt{PREIMG}] &
% $\sos{\lhd_{\sigma}^{\varphi}}{\lblfunv}{\id}{\lambda v . f_\sigma(f_\varphi((\lblfunv, \lblfune)(\inset{\graph}{v})), \lblfunv(v))}$ \\[5mm]

% [\texttt{POSTIMG}] &
% $\sos{\rhd_{\sigma}^{\varphi}}{\lblfunv}{\id}{\lambda v . f_\sigma(f_\varphi((\lblfunv, \lblfune)(\outset{\graph}{v})), \lblfunv(v))}$ \\[5mm]
\begin{proof}
    By induction on typing derivations.
        \begin{description}
        \item[Case \texttt{T-ID}:] We have $\mathcal{N} = \id : \gnntype{T}{T}$ and $\lblfunv: \lblfunvtype{T}$. The only applicable rule is \texttt{ID} by which $\sosv{\id}{\lblfunv}{\lblfunv} : \lblfunvtype{T}$.

        \item[Case \texttt{T-PSI}:] We have $\psi: \gnntype{T_1}{T_2}$ and $\lblfunv: \lblfunvtype{T_1}$, with $f_\psi: T_1^\star \times T_1 \rightarrow T_2$. The only rule that can be applied is \texttt{APPLY} which gives $\mathcal{N}' = \id$ and $\lblfunv' = \lambda v . f_{\psi}(\lblfunv(\vSet), \lblfunv(v))$. Then $\lblfunv'$ has type $\lblfunvtype{T_2}$ and $\id$ has type $\gnntype{T_2}{T_2}$ by rule \texttt{T-ID}.

        \item[Case \texttt{T-PRE}:] We have $\lhd_\sigma^\varphi : \gnntype{T_1}{T_3}$ and $\lblfunv: \lblfunvtype{T_1}$, with $f_\varphi: T_1 \times T_e \times T_1 \rightarrow T_2$ and $f_\sigma: T_2^\star \times T_1 \rightarrow T_3$. The only rule that can be applied is \texttt{PREIMG} which gives $\mathcal{N}' = \id$ and $\lblfunv' = \lambda v . f_\sigma([f_\varphi(\lblfunv(u), \lblfune((u, v)), \lblfunv(v)) \mid (u, v) \in \inset{\graph}{v}], \lblfunv(v))$. Then $\lblfunv'$ has type $\lblfunvtype{T_3}$ and $\id$ has type $\gnntype{T_3}{T_3}$ by rule \texttt{T-ID}.

        \item[Case \texttt{T-POST}:] Analogous to \texttt{T-PRE}, but using rule \texttt{POSTIMG} instead.

        \item[Case \texttt{T-SEQ}:] We have $\mathcal{N}_1 ; \mathcal{N}_2 : \gnntype{T_1}{T_3}$ and $\lblfunv : \lblfunvtype{T_1}$. We also have sub-derivations with conclusions that $\mathcal{N}_1 : \gnntype{T_1}{T_2}$ and $\mathcal{N}_2 : \gnntype{T_2}{T_3}$. There are two possible rules that can be applied, $\texttt{SEQ}_1$ and $\texttt{SEQ}_2$. 
        \begin{itemize}
            \item In the case of $\texttt{SEQ}_1$, we have $\mathcal{N}' = \mathcal{N}_1' ; \mathcal{N}_2$. By applying the induction hypothesis on $\mathcal{N}_1$ we get that $\lblfunv' : \lblfunvtype{T}$ and $\mathcal{N}_1' : \gnntype{T}{T_2}$ for some node-labeling type $\lblfunvtype{T}$. Then we can apply rule \texttt{T-SEQ} on $\mathcal{N}_1' ; \mathcal{N}_2$ to get its type $\gnntype{T}{T_3}$.
            \item In the case of $\texttt{SEQ}_2$, then $\mathcal{N}_1 = \id$, $T_1 = T_2$ and we have $\mathcal{N}' = \mathcal{N}_2$, which we know to have type $\gnntype{T_1}{T_3}$, and $\lblfunv' = \lblfunv$, which we know to have type $\lblfunvtype{T_1}$. 
        \end{itemize}

        \item[Case \texttt{T-PAR}:] We have $\mathcal{N}_1 || \mathcal{N}_2 : \gnntype{T}{T_1 \times T_2}$ and $\lblfunv : \lblfunvtype{T}$. We also have sub-derivations with conclusions that $\mathcal{N}_1 : \gnntype{T}{T_1}$ and $\mathcal{N}_2 : \gnntype{T}{T_2}$. The only rule that can be applied is \texttt{SPLIT}. Then $\lblfunv' = \lblfunv | \lblfunv : \lblfunvtype{T \times T}$ and $\mathcal{N}' = \mathcal{N}_1 \parcomp \mathcal{N}_2$ which by rule \texttt{T-PROD} has type $\gnntype{T \times T}{T_1 \times T_2}$.

        \item[Case \texttt{T-PROD}:] We have $\mathcal{N}_1 \parcomp \mathcal{N}_2 : \gnntype{T_1 \times T_2}{T_1' \times T_2'}$ and $\lblfunv : \lblfunvtype{T_1 \times T_2}$. We also have sub-derivations with conclusions that $\mathcal{N}_1 : \gnntype{T_1}{T_1'}$ and $\mathcal{N}_2 : \gnntype{T_2}{T_2'}$. There are three possible rules that can be applied, $\texttt{PAR}_1, \texttt{PAR}_2$, and $\texttt{MERGE}$.
        \begin{itemize}
            \item In the case of $\texttt{PAR}_1$, we have $\mathcal{N}' = \mathcal{N}_1' \parcomp \mathcal{N}_2$ and $\lblfunv' = \lblfunv_1 | \pi_R(\lblfunv)$. By applying the induction hypothesis on $\mathcal{N}_1$ we get that $\lblfunv_1 : \lblfunvtype{T}$ and $\mathcal{N}_1' : \gnntype{T}{T_1'}$ for some node-labeling type $\lblfunvtype{T}$. Then we can apply rule \texttt{T-PROD} on $\mathcal{N}_1' \parcomp \mathcal{N}_2$ to get its type $\gnntype{T \times T_2}{T_1' \times T_2'}$, and $\lblfunv': \lblfunvtype{T \times T_2}$.
            \item The case of $\texttt{PAR}_2$ is analogous to that of $\texttt{PAR}_1$.
            \item In the case of $\texttt{MERGE}$, we have $\mathcal{N}' = \id$ and $\lblfunv' = \lblfunv$. Furthermore, this rule could have been applied only if $\mathcal{N}_1 = \mathcal{N}_2 = \id$, which means that $T_1 = T_1'$ and $T_2 = T_2'$. Then by rule \texttt{T-ID} we get that $\id: \gnntype{T_1' \times T_2'}{T_1' \times T_2'}$.
        \end{itemize}


        \item[Case \texttt{T-CHOICE}:] We have $\mathcal{N}_1 \choiceop \mathcal{N}_2: \gnntype{\mathbb{B} \times T_1}{T_2}$ and $\lblfunv: \lblfunvtype{\mathbb{B} \times T_1}$.  We also have sub-derivations with conclusions that $\mathcal{N}_1 : \gnntype{T_1}{T_2}$ and $\mathcal{N}_2 : \gnntype{T_1}{T_2}$. There are two possible rules that can be applied, $\texttt{CHOICE}_1$ and $\texttt{CHOICE}_2$.
        \begin{itemize}
            \item In case $\texttt{CHOICE}_1$, we have $\lblfunv' = \pi_R(\lblfunv) : \lblfunvtype{T_1}$ and $\mathcal{N}' = \mathcal{N}_1$ which we know to have type $\gnntype{T_1}{T_2}$.
            \item In case $\texttt{CHOICE}_2$, we have $\lblfunv' = \pi_R(\lblfunv) : \lblfunvtype{T_1}$ and $\mathcal{N}' = \mathcal{N}_2$ which we know to have type $\gnntype{T_1}{T_2}$.
        \end{itemize}


        \item[Case \texttt{T-STAR}:]  We have $\starop{\mathcal{N}}: \gnntype{T}{T}$ and $\lblfunv: \lblfunvtype{T}$. We also have a subderivation with the conclusion that $\mathcal{N}: \gnntype{T}{T}$. The only rule that can be applied is \texttt{STAR}. Then $\lblfunv' = \lblfunv : \lblfunvtype{T}$ and $\mathcal{N}' = ((\id || \mathcal{N}) ; \psi_{\simop} || \id) ; (\id \choiceop \mathcal{N} ; \starop{\mathcal{N}})$.  To type this term, first we infer the type of the left-hand side of the sequential composition
        %
        \[\resizebox{0.94\textwidth}{!}{
        \inference[\texttt{T-PAR}]{
        \inference[\texttt{T-SEQ}]{
        \inference[\texttt{T-PAR}]{
        \inference[\texttt{T-ID}]{}{\id: \gnntype{T}{T}} & \mathcal{N}: \gnntype{T}{T}
        }{\id || \mathcal{N} : \gnntype{T}{T \times T}}
        &
        \inference[\texttt{T-PSI}]{\Gamma |- f_{\psi_{\simop}}: (T \times T)^{*} \times (T \times T) \rightarrow \mathbb{B}}{\psi_{\simop}: \gnntype{T \times T}{\mathbb{B}}}
        }{(\id || \mathcal{N}) ; \psi_{\simop} : \gnntype{T}{\mathbb{B}}}
        &
        \inference[\texttt{T-ID}]{}{\id: \gnntype{T}{T}}
        }{(\id || \mathcal{N}) ; \psi_{\simop} || \id : \gnntype{T}{\mathbb{B} \times T}}
        }\]
        %
        We proceed likewise for the right-hand side
        %
        \[
        \inference[\texttt{T-CHOICE}]{
        \inference[\texttt{T-ID}]{}{\id: \gnntype{T}{T}}
        &
        \inference[\texttt{T-SEQ}]{\mathcal{N}: \gnntype{T}{T}
        &
        \starop{\mathcal{N}} : \gnntype{T}{T}}{\mathcal{N} ; \starop{\mathcal{N}} : \gnntype{T}{T}}
        }{\id \choiceop \mathcal{N} ; \starop{\mathcal{N}} : \gnntype{\mathbb{B} \times T}{T}}\]
        %
        Finally, we can apply rule \texttt{T-SEQ} to infer
        %
        \[
        \inference[\texttt{T-SEQ}]{(\id || \mathcal{N}) ; \psi_{\simop} || \id : \gnntype{T}{\mathbb{B} \times T} & \id \choiceop \mathcal{N} ; \starop{\mathcal{N}} : \gnntype{\mathbb{B} \times T}{T}
        }
        {((\id || \mathcal{N}) ; \psi_{\simop} || \id) ; (\id \choiceop \mathcal{N} ; \starop{\mathcal{N}}): \gnntype{T}{T}}\]
        as required.
    \end{description}
\end{proof}


\section{A graphical representation}\label{sec:graphics}
In this section, we present a graphical representation for $\mG$ programs and expressions. Using such graphical notation makes it easier to understand and communicate the structure and purpose of a $\mG$ program, as the programmer might easily lose track of label types and sizes when developing in textual form. The basic terms of $\mG$ can be represented graphically as boxes, as shown in Figure~\ref{fig:basic-repr}, while the composite terms of the language are shown in Figure~\ref{fig:comp-repr}. Each term has exactly one input node-labeling function and one output node-labeling function, and the graphical representation is built top-down starting from the main (usually composite) term and substituting each box with either a basic term or a composite one; in this last case, this procedure is repeated recursively until all boxes in the figure are basic terms. As an illustrative example, let $\psi_1, \psi_2, \psi_3, \varphi, \sigma$ be function symbols. Figure~\ref{fig:example} shows how we can represent graphically the $\mu\mathcal{G}$ expression $(\psi_1 || \psi_2);\psi_3;\lhd_{\sigma}^{\varphi}$. 

