\section{Implementation Details}
\label{sec:pssm}
This section details the implementation of spikingPssm. The model's simplicity allows implementation by adding just a few lines of code to the s4d \cite{gu2021combining} framework,specifically the spiking module in the following algorithm, as spikingPssm essentially combines SSM with PSN\cite{fang2023parallel}'s spiking mechanism.

\begin{algorithm}
\caption{spikingPssm Forward Pass}
\begin{algorithmic}[1]
\State \textbf{Input:} $u$ (shape $B \times H \times L$) \Comment{B: batch size, H: model dimension, L: sequence length}
\State \textbf{Output:} $y$, sparsity ratio $r$
\Statex \rule{\linewidth}{0.4pt}
\State $\textbf{Memory Module}$ 
\State $k \gets \text{S4DKernel}(L)$ 
\State $y \gets \text{FFT\_Conv}(u, k)$
\State $y \gets y +  Du$ \Comment{Core s4d operations}
\Statex \rule{\linewidth}{0.4pt}
\State $\textbf{Spiking Module}$
\State Pad $y$ to length $L + \text{padding}$ 
\State $y1 \gets \text{conv}(y)$ 
\Statex $conv = nn.Conv1d(H, H, kernelsize=reset, stride=reset, bias=False, groups=H)$
\Statex This configuration ensures each neuron only requires one floating-point multiplication per timestep, eliminating cross-channel computations - analogous to LIF's membrane potential decay (multiplied by $1-\frac{1}{\tau}$ each step). Here, $reset$ corresponds to refractory period/convolution kernel length, reducing sequence length to $(L+padding)/reset$.
\State $y1 \gets \text{layernorm}(y1)$
\State $y1 \gets \text{H}(y1)$ \Comment{Heaviside step function}
\State $y\gets y1.\text{repeat\_interleave}(reset)$ \Comment{Replicate each timestep $reset$ times to restore original length}
\Statex \rule{\linewidth}{0.4pt}
\State $\textbf{Nonlinear Channel-Mixer}$
\State $y \gets \text{dropout}(y)$ 
\State $y \gets \text{GLU}(y)$

\State \Return $y$
\end{algorithmic}
\end{algorithm}





