\section{Algorithm of $\mathrm{ASA_{grad}}$}
In this section, we present the pseudocode of the $\mathrm{ASA_{grad}}$ algorithm in Alg.~\ref{alg:gasa}.

\begin{algorithm}
\caption{$\mathrm{ASA_{grad}}$ (Gradient-based Activation Steering Attack)}
\begin{algorithmic}[1]
\State \textbf{Input:} Initial prompt $x_{\text{prompt}}$, target suffix $x_{\text{target}}$, target layer $l$
\State \textbf{Construct:} Concatenated input $x = x_{\text{prompt}} + x_{\text{target}}$
\State Compute loss $\mathcal{L}(x)$ at layer $l$
\State Compute gradient $\nabla_{a_l} \mathcal{L}(x)$ with respect to the activation $a_l$ at layer $l$
\State Extract activation $a_l^{\text{last}}$ of the final token in $x_{\text{prompt}}$
\State Normalize the gradient using Eq.~(\ref{eq:grad_norm}): $\hat{g} \leftarrow \mathrm{Normalized}(a_l^{\mathrm{last}}, \nabla_{a_l}\mathcal{L}(x))$
\State Compute steered activation: $a_l^{\text{steered}} = a_l^{\text{last}} + \alpha \cdot \hat{g}$
\end{algorithmic}
\label{alg:gasa}
\end{algorithm}
