\begin{algorithm}[ht]
\caption{SecureFed: Two-Phase Framework with Trust-Zone Weighted Aggregation}
\begin{algorithmic}[1]
\REQUIRE Initial global model $\mathcal{M}_g^0$, client set $\mathcal{C}$, public dataset $D_p$, synthetic dataset $D_s$, number of rounds $R$
\ENSURE Final global model $\mathcal{M}_g^R$

\FOR{each round $r = 1$ to $R$}
    \STATE Server broadcasts $\mathcal{M}_g^r$ to all clients $\mathcal{C}$
    \FOR{each client $c \in \mathcal{C}$ in parallel}
        \STATE Client $c$ trains and returns $\mathcal{W}_c^r$
    \ENDFOR

    \STATE \textbf{Phase 1: Anomaly Detection}
    \STATE Collect all client updates: $\{\mathcal{W}_c^r\}$
    \STATE Apply dimensionality reduction: $\tilde{\mathcal{W}}_c^r = DR(\mathcal{W}_c^r)$
    \STATE Compute anomaly scores: $A_c = f_{\text{anomaly}}(\tilde{\mathcal{W}}_c^r)$
     % \STATE Compute threshold :  $\tau^*$
    \STATE Estimate detection threshold via synthetic evaluation: $\tau^* = \text{Validate}(D_s, \{A_c\})$

    \STATE \textbf{Phase 2: Adaptive Learning Zones}
    \FOR{each client $c$}
        \STATE Temporarily update model: $\mathcal{M}_c^r = \mathcal{M}_g^r + \mathcal{W}_c^r$
        \STATE Evaluate $\mathcal{M}_c^r$ on synthetic data $D_s$ to compute validation loss: $L_c$
        \STATE Compute gradient magnitude: $G_c = \|\nabla \mathcal{W}_c^r\|$
        \STATE Compute trust score: $T_c = \alpha \cdot \left(1 - \frac{A_c}{\tau^*} \right) + \beta \cdot \left(1 - \frac{L_c}{\max(L)} \right) + \gamma \cdot \frac{G_c}{\max(G)}$

        \IF{$T_c \geq \tau_{\text{high}}$}
            \STATE Assign $c$ to Zone 1 (High Trust), set $\alpha_z(c) = \alpha_1$
        \ELSIF{$\tau_{\text{low}} \leq T_c < \tau_{\text{high}}$}
            \STATE Assign $c$ to Zone 2 (Uncertain), set $\alpha_z(c) = \alpha_2$
        \ELSE
            \STATE Assign $c$ to Zone 3 (Low Trust), set $\alpha_z(c) = \alpha_3$
        \ENDIF
    \ENDFOR

    \STATE \textbf{Weighted Aggregation from All Zones:}
    \STATE $\mathcal{W}_{r+1} \leftarrow \frac{\sum\limits_{c \in \mathcal{C}} \alpha_z(c) \cdot n_c \cdot \mathcal{W}_c^r}{\sum\limits_{c \in \mathcal{C}} \alpha_z(c) \cdot n_c}$
    \STATE Update global model: $\mathcal{M}_g^{r+1} \leftarrow \mathcal{M}_g^r + \mathcal{W}_{r+1}$

\ENDFOR

\RETURN Final global model $\mathcal{M}_g^R$
\end{algorithmic}
\label{securefed_weighted}
\end{algorithm}

